// Fails if a page in docs/ is missing from the navigation (sidebars.mjs),
// or if the English (docs/) and French (i18n/fr/...) page sets differ.
// Pages in folders listed automatically ("autogenerated") are covered by design.
import {existsSync, readdirSync, statSync} from 'node:fs';
import {join, relative, sep} from 'node:path';
import sidebars from '../sidebars.mjs';

const docsDir = 'docs';
const frDir = 'i18n/fr/docusaurus-plugin-content-docs/current';

function listPages(root, dir = root) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return listPages(root, path);
    return /\.mdx?$/.test(name) ? [relative(root, path).split(sep).join('/').replace(/\.mdx?$/, '')] : [];
  });
}

const ids = new Set();
const autoDirs = [];
function walk(item) {
  if (typeof item === 'string') ids.add(item);
  else if (Array.isArray(item)) item.forEach(walk);
  else if (item.type === 'doc') ids.add(item.id);
  else if (item.type === 'autogenerated') autoDirs.push(item.dirName);
  else if (item.items) walk(item.items);
}
Object.values(sidebars).forEach(walk);

const en = listPages(docsDir);
const fr = new Set(listPages(frDir));
const errors = [];
const missingFromNav = en.filter((p) => !ids.has(p) && !autoDirs.some((d) => p.startsWith(`${d}/`)));
if (missingFromNav.length) errors.push(`Pages missing from the navigation (sidebars.mjs):\n  ${missingFromNav.join('\n  ')}`);
const noFrench = en.filter((p) => !fr.has(p));
if (noFrench.length) errors.push(`English pages without a French version:\n  ${noFrench.join('\n  ')}`);
const noEnglish = [...fr].filter((p) => !en.includes(p));
if (noEnglish.length) errors.push(`French pages without an English version:\n  ${noEnglish.join('\n  ')}`);

if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}
console.log(`Navigation: all ${en.length} pages are in the navigation, in English and French.`);
